{
  "version": 1,
  "operations": {
    "text.replace": {
      "description": "Replace literal Unicode text across adjacent runs. Paragraphs, fields and breaks stop matches. Replacement inherits the first affected run style. No Unicode normalization or fine-grained range selectors.",
      "input": {
        "type": "string",
        "minLength": 1,
        "description": "Explicit VFS path, or - for stdin."
      },
      "options": {
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "json": {
            "type": "boolean"
          },
          "limit": {
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "maxBytes": {
                "type": "integer",
                "minimum": 1
              },
              "maxNodes": {
                "type": "integer",
                "minimum": 1
              },
              "maxDepth": {
                "type": "integer",
                "minimum": 1
              },
              "maxOutputBytes": {
                "type": "integer",
                "minimum": 512
              }
            },
            "description": "CLI repeats --limit NAME=VALUE for distinct names; all values must lower explicit trusted ceilings."
          },
          "select": {
            "type": "string",
            "minLength": 1
          },
          "slide": {
            "type": "integer",
            "minimum": 1,
            "maximum": 9007199254740991,
            "description": "One-based slide-list position."
          },
          "shape": {
            "type": "string",
            "minLength": 1,
            "description": "Exact case-sensitive name, including numeric strings."
          },
          "scope": {
            "enum": [
              "slides",
              "notes",
              "layouts",
              "masters",
              "notes-master",
              "handout-master"
            ]
          },
          "style": {
            "type": "object",
            "additionalProperties": false,
            "minProperties": 1,
            "description": "CLI --style-json; override only replacement run bold/italic, retaining first-run other style properties.",
            "properties": {
              "bold": {
                "type": "boolean"
              },
              "italic": {
                "type": "boolean"
              }
            }
          },
          "find": {
            "type": "string",
            "minLength": 1
          },
          "with": {
            "type": "string"
          },
          "first": {
            "type": "boolean"
          },
          "all": {
            "type": "boolean"
          },
          "occurrence": {
            "type": "integer",
            "minimum": 1,
            "maximum": 9007199254740991
          },
          "allowEmpty": {
            "type": "boolean"
          },
          "output": {
            "type": "string",
            "minLength": 1
          },
          "inPlace": {
            "type": "boolean"
          },
          "force": {
            "type": "boolean"
          },
          "dryRun": {
            "type": "boolean"
          }
        },
        "allOf": [
          {
            "if": {
              "required": [
                "slide"
              ]
            },
            "then": {
              "properties": {
                "scope": {
                  "enum": [
                    "slides",
                    "notes",
                    "layouts",
                    "masters"
                  ]
                }
              }
            }
          },
          {
            "if": {
              "required": [
                "select"
              ]
            },
            "then": {
              "not": {
                "anyOf": [
                  {
                    "required": [
                      "scope"
                    ]
                  },
                  {
                    "required": [
                      "slide"
                    ]
                  },
                  {
                    "required": [
                      "shape"
                    ]
                  }
                ]
              }
            }
          },
          {
            "if": {
              "required": [
                "shape"
              ]
            },
            "then": {
              "required": [
                "slide"
              ]
            }
          },
          {
            "if": {
              "required": [
                "inPlace"
              ],
              "properties": {
                "inPlace": {
                  "const": true
                }
              }
            },
            "then": {
              "not": {
                "required": [
                  "output"
                ]
              }
            }
          },
          {
            "if": {
              "required": [
                "force"
              ],
              "properties": {
                "force": {
                  "const": true
                }
              }
            },
            "then": {
              "required": [
                "output"
              ]
            }
          },
          {
            "anyOf": [
              {
                "required": [
                  "output"
                ]
              },
              {
                "required": [
                  "inPlace"
                ],
                "properties": {
                  "inPlace": {
                    "const": true
                  }
                }
              },
              {
                "required": [
                  "dryRun"
                ],
                "properties": {
                  "dryRun": {
                    "const": true
                  }
                }
              }
            ]
          },
          {
            "if": {
              "required": [
                "output",
                "json"
              ],
              "properties": {
                "output": {
                  "const": "-"
                },
                "json": {
                  "const": true
                }
              }
            },
            "then": {
              "required": [
                "dryRun"
              ],
              "properties": {
                "dryRun": {
                  "const": true
                }
              }
            }
          },
          {
            "oneOf": [
              {
                "required": [
                  "first"
                ],
                "properties": {
                  "first": {
                    "const": true
                  }
                },
                "not": {
                  "anyOf": [
                    {
                      "required": [
                        "all"
                      ]
                    },
                    {
                      "required": [
                        "occurrence"
                      ]
                    }
                  ]
                }
              },
              {
                "required": [
                  "all"
                ],
                "properties": {
                  "all": {
                    "const": true
                  }
                },
                "not": {
                  "anyOf": [
                    {
                      "required": [
                        "first"
                      ]
                    },
                    {
                      "required": [
                        "occurrence"
                      ]
                    }
                  ]
                }
              },
              {
                "required": [
                  "occurrence"
                ],
                "not": {
                  "anyOf": [
                    {
                      "required": [
                        "first"
                      ]
                    },
                    {
                      "required": [
                        "all"
                      ]
                    }
                  ]
                }
              }
            ]
          }
        ],
        "required": [
          "find",
          "with"
        ]
      },
      "result": {
        "$schema": "https://json-schema.org/draft/2020-12/schema",
        "type": "object",
        "additionalProperties": false,
        "required": [
          "version",
          "operation",
          "ok",
          "data",
          "warnings",
          "errors",
          "affected",
          "locations"
        ],
        "properties": {
          "version": {
            "const": 1
          },
          "operation": {
            "const": "text.replace"
          },
          "ok": {
            "type": "boolean"
          },
          "affected": {
            "type": "integer",
            "minimum": 0
          },
          "data": {
            "oneOf": [
              {
                "type": "null"
              },
              {
                "type": "object",
                "additionalProperties": false,
                "required": [
                  "replacements",
                  "dryRun"
                ],
                "properties": {
                  "replacements": {
                    "type": "integer",
                    "minimum": 0
                  },
                  "dryRun": {
                    "type": "boolean"
                  }
                }
              }
            ]
          },
          "warnings": {
            "type": "array",
            "items": {
              "$ref": "#/$defs/diagnostic"
            }
          },
          "errors": {
            "type": "array",
            "items": {
              "$ref": "#/$defs/diagnostic"
            }
          },
          "locations": {
            "type": "array",
            "items": {
              "$ref": "#/$defs/location"
            }
          }
        },
        "allOf": [
          {
            "if": {
              "properties": {
                "ok": {
                  "const": true
                }
              }
            },
            "then": {
              "properties": {
                "data": {
                  "type": "object"
                },
                "errors": {
                  "maxItems": 0
                }
              }
            },
            "else": {
              "properties": {
                "data": {
                  "type": "null"
                },
                "errors": {
                  "minItems": 1
                },
                "locations": {
                  "maxItems": 0
                }
              }
            }
          }
        ],
        "$defs": {
          "inventoryPart": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "part",
              "contentType",
              "bytes",
              "sha256"
            ],
            "properties": {
              "part": {
                "type": "string"
              },
              "contentType": {
                "type": [
                  "string",
                  "null"
                ]
              },
              "bytes": {
                "type": "integer",
                "minimum": 0
              },
              "sha256": {
                "type": "string",
                "minLength": 64,
                "maxLength": 64
              }
            }
          },
          "location": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "fingerprint",
              "scope",
              "owner",
              "objectId",
              "coordinateSystem"
            ],
            "properties": {
              "fingerprint": {
                "type": "string"
              },
              "scope": {
                "enum": [
                  "slides",
                  "notes",
                  "layouts",
                  "masters",
                  "notes-master",
                  "handout-master",
                  "presentation",
                  "shared"
                ]
              },
              "owner": {
                "type": "string"
              },
              "objectId": {
                "type": "string"
              },
              "coordinateSystem": {
                "const": "identity"
              }
            }
          },
          "record": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "kind",
              "id",
              "name",
              "part",
              "scope",
              "position",
              "location",
              "token"
            ],
            "properties": {
              "kind": {
                "enum": [
                  "slide",
                  "part",
                  "object"
                ]
              },
              "id": {
                "type": "string"
              },
              "name": {
                "type": "string"
              },
              "part": {
                "type": "string"
              },
              "scope": {
                "enum": [
                  "slides",
                  "notes",
                  "layouts",
                  "masters",
                  "notes-master",
                  "handout-master",
                  "presentation",
                  "shared"
                ]
              },
              "position": {
                "type": "integer",
                "minimum": 1
              },
              "objectType": {
                "type": "string"
              },
              "location": {
                "$ref": "#/$defs/location"
              },
              "token": {
                "type": "string"
              }
            }
          },
          "diagnostic": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "code",
              "message",
              "context"
            ],
            "properties": {
              "code": {
                "type": "string"
              },
              "message": {
                "type": "string"
              },
              "context": {
                "type": "object",
                "additionalProperties": false,
                "required": [
                  "phase"
                ],
                "properties": {
                  "phase": {
                    "type": "string"
                  },
                  "candidates": {
                    "type": "array",
                    "items": {
                      "$ref": "#/$defs/location"
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}
